{
  "name": "LabJack多功能数据采集模块",
  "name_en": "LabJack multifunction DAQ module",
  "manufacturer": "LabJack",
  "description": "LabJack多功能数据采集模块是一种带模拟与数字输入输出接口的实验室数据采集和控制设备，可用于读取传感器电压信号、输出模拟控制电压，以及控制或监测数字开关量，常用于通用自动化、仪器联动和实验数据采集。",
  "description_en": "A LabJack multifunction DAQ module is a laboratory data acquisition and control device with analog and digital I/O. It is used to read sensor voltages, output analog control voltages, and control or monitor digital logic signals in general automation, instrument integration, and experimental data acquisition.",
  "tag_hints": [
    "data acquisition",
    "analog input",
    "analog output",
    "digital I/O",
    "sensor voltage measurement",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化LabJack数据采集模块并建立通信。",
      "description_en": "Initialize the LabJack DAQ module and establish communication."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭LabJack数据采集模块并断开通信。",
      "description_en": "Shut down the LabJack DAQ module and disconnect communication."
    },
    {
      "action_name": "auto-setConfiguration",
      "description": "设置设备配置参数，如通道或输入输出相关设置。",
      "description_en": "Set device configuration parameters, such as channel settings or I/O-related options."
    },
    {
      "action_name": "auto-configuration",
      "description": "获取当前设备配置。",
      "description_en": "Get the current device configuration."
    },
    {
      "action_name": "auto-getAnalogVoltage",
      "description": "读取指定模拟通道的电压。",
      "description_en": "Read the voltage on a specified analog channel."
    },
    {
      "action_name": "auto-setAnalogVoltage",
      "description": "设置指定模拟输出通道的电压。",
      "description_en": "Set the voltage on a specified analog output channel."
    },
    {
      "action_name": "auto-setDigitalValue",
      "description": "设置指定数字通道的逻辑电平状态。",
      "description_en": "Set the logic level state of a specified digital channel."
    },
    {
      "action_name": "auto-getDigitalValue",
      "description": "读取指定数字通道的逻辑电平状态。",
      "description_en": "Read the logic level state of a specified digital channel."
    }
  ]
}

